"use client";
import type { ButtonHTMLAttributes } from "react";
import "./lens-button.css";

/** Dark glass with a spotlight edge and a soft refraction that follow the pointer. */
export function LensButton({
  children,
  className = "",
  type = "button",
  ...props
}: ButtonHTMLAttributes<HTMLButtonElement>) {
  return (
    <button
      {...props}
      type={type}
      className={`forme-lens ${className}`}
      onPointerMove={(e) => {
        const r = e.currentTarget.getBoundingClientRect();
        e.currentTarget.style.setProperty("--forme-lens-x", `${e.clientX - r.left}px`);
        e.currentTarget.style.setProperty("--forme-lens-y", `${e.clientY - r.top}px`);
        props.onPointerMove?.(e);
      }}
      onPointerLeave={(e) => {
        e.currentTarget.style.removeProperty("--forme-lens-x");
        e.currentTarget.style.removeProperty("--forme-lens-y");
        props.onPointerLeave?.(e);
      }}
    >
      <span className="forme-lens-label">{children}</span>
    </button>
  );
}

.forme-lens {
  --forme-lens-x: 50%;
  --forme-lens-y: 0%;
  --forme-lens-tint: #7c9cff;
  position: relative;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  height: 50px;
  padding: 0 28px;
  border: 0;
  border-radius: 999px;
  background:
    radial-gradient(140px circle at var(--forme-lens-x) var(--forme-lens-y), #ffffff1c, transparent 65%),
    linear-gradient(180deg, #1b1b20, #0b0b0e);
  box-shadow:
    inset 0 1px 0 #ffffff12,
    inset 0 -1px 0 #00000080,
    0 12px 32px -12px #000000e6;
  color: #f4f4f5;
  font: inherit;
  font-size: 15px;
  font-weight: 500;
  letter-spacing: -0.005em;
  cursor: pointer;
  transition: transform 0.25s cubic-bezier(0.2, 0.8, 0.2, 1);
}
/* A one-pixel edge, brightest where the light sits. */
.forme-lens::before {
  content: "";
  position: absolute;
  inset: 0;
  padding: 1px;
  border-radius: inherit;
  background: radial-gradient(
    110px circle at var(--forme-lens-x) var(--forme-lens-y),
    #ffffffe6,
    #ffffff2e 45%,
    #ffffff14 70%
  );
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}
/* Colored light bleeding through the glass from below. */
.forme-lens::after {
  content: "";
  position: absolute;
  inset: 6px 14px -4px;
  z-index: -1;
  border-radius: inherit;
  background: radial-gradient(70px circle at var(--forme-lens-x) 100%, var(--forme-lens-tint), transparent 75%);
  filter: blur(14px);
  opacity: 0;
  transition: opacity 0.35s;
}
.forme-lens-label {
  position: relative;
  text-shadow: 0 1px 12px #ffffff26;
}
.forme-lens:hover::after,
.forme-lens:focus-visible::after {
  opacity: 0.7;
}
.forme-lens:focus-visible {
  --forme-lens-x: 50%;
  --forme-lens-y: 50%;
  outline: 2px solid #f4f4f5;
  outline-offset: 4px;
}
.forme-lens:active {
  transform: scale(0.975);
}
.forme-lens:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
@media (prefers-reduced-motion: reduce) {
  .forme-lens,
  .forme-lens::after {
    transition: none;
  }
  .forme-lens:active {
    transform: none;
  }
}
